<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import {
  shortDramaApi, type WorldCandidate, type WorldCharacter, type WorldLocation,
  type WorldOverview, type WorldProp, type WorldRelationship,
} from '@/api/modules'
import AssetPicker from '@/v2/components/AssetPicker.vue'
import GlassDrawer from '@/v2/components/GlassDrawer.vue'
import MediaViewer from '@/v2/components/MediaViewer.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import type { ResourceItem } from '@/v2/features/assets/model'
import type { TaskOutput } from '@/v2/features/tasks/model'

type Tab = 'characters'|'locations'|'props'|'relationships'
const route=useRoute();const router=useRouter();const projectId=computed(()=>Number(route.params.id))
const world=ref<WorldOverview>({characters:[],locations:[],props:[],relationships:[]})
const active=ref<Tab>('characters');const loading=ref(true);const working=ref(false);const error=ref('');const notice=ref('')
const candidate=ref<WorldCandidate|null>(null);const drawer=ref(false);const editingId=ref<number|null>(null);const form=ref<Record<string,any>>({})
const variantEditingId=ref<number|null>(null);const variantForm=ref({name:'',description:'',wardrobe:'',hairstyle:'',makeup:'',primary_resource_id:null as number|null,reference_resource_ids:[] as number[],source_references:[] as any[]})
const picker=ref(false);const pickerType=ref<'image'|'video'|'audio'>('image');const selectedResources=ref(new Map<number,ResourceItem>());const preview=ref<TaskOutput|null>(null)
const tabs=[{key:'characters',label:'角色',icon:'人'},{key:'locations',label:'地点',icon:'景'},{key:'props',label:'道具',icon:'物'},{key:'relationships',label:'关系',icon:'联'}] as const
const currentItems=computed<any[]>(()=>world.value[active.value]||[])
const candidatePayload=computed(()=>candidate.value?.payload||{})
const kindLabel=computed(()=>tabs.find(item=>item.key===active.value)?.label||'设定')

function apiMessage(event:any,fallback:string){return event.response?.data?.detail||event.response?.data?.message||fallback}
async function load(){loading.value=true;error.value='';try{world.value=await shortDramaApi.world(projectId.value)}catch(event:any){error.value=apiMessage(event,'世界设定加载失败')}finally{loading.value=false}}
async function extract(){working.value=true;error.value='';notice.value='';try{candidate.value=await shortDramaApi.extractWorld(projectId.value)}catch(event:any){error.value=apiMessage(event,'设定提取失败')}finally{working.value=false}}
async function confirmCandidate(){if(!candidate.value)return;working.value=true;try{candidate.value=await shortDramaApi.confirmWorld(projectId.value,candidate.value.id,true);notice.value='候选设定已确认；同名人工设定已保留，未被覆盖。';await load()}catch(event:any){error.value=apiMessage(event,'候选确认失败')}finally{working.value=false}}
function defaults(tab:Tab){
  const common={name:'',source_references:[],reference_resource_ids:[],status:'draft'}
  if(tab==='characters')return{...common,aliases:[],identity:'',age_appearance:'',appearance:'',personality:'',relationships:{},negative_traits:[],primary_resource_id:null}
  if(tab==='locations')return{...common,description:'',spatial_layout:'',time_weather:'',lighting:'',color_palette:[],fixed_objects:[],primary_resource_id:null}
  if(tab==='props')return{...common,description:'',appearance:'',appearance_scope:'',owner_character_id:null,continuity_note:'',resource_id:null}
  return{source_character_id:world.value.characters[0]?.id||null,target_character_id:world.value.characters[1]?.id||null,relationship_type:'关联',description:'',source_references:[],status:'draft'}
}
function resetVariant(){variantEditingId.value=null;variantForm.value={name:'',description:'',wardrobe:'',hairstyle:'',makeup:'',primary_resource_id:null,reference_resource_ids:[],source_references:[]}}
function openCreate(){editingId.value=null;form.value=defaults(active.value);selectedResources.value=new Map();resetVariant();drawer.value=true}
function openEdit(item:any){editingId.value=item.id;form.value=structuredClone(item);selectedResources.value=new Map();resetVariant();drawer.value=true}
function split(value:string){return value.split(/[，,\n]/).map(item=>item.trim()).filter(Boolean)}
function normalizeBody(){
  const body={...form.value};for(const key of ['id','owner_id','project_id','created_at','updated_at'])delete body[key]
  delete body.variants
  if(active.value==='characters'){body.aliases=Array.isArray(body.aliases)?body.aliases:split(body.aliases||'');body.negative_traits=Array.isArray(body.negative_traits)?body.negative_traits:split(body.negative_traits||'')}
  if(active.value==='locations'){body.color_palette=Array.isArray(body.color_palette)?body.color_palette:split(body.color_palette||'');body.fixed_objects=Array.isArray(body.fixed_objects)?body.fixed_objects:split(body.fixed_objects||'')}
  return body
}
async function save(){working.value=true;error.value='';try{const body=normalizeBody();if(editingId.value)await shortDramaApi.updateWorldItem(projectId.value,active.value,editingId.value,body);else await shortDramaApi.createWorldItem(projectId.value,active.value,body);drawer.value=false;notice.value=`${kindLabel.value}设定已保存`;await load()}catch(event:any){error.value=apiMessage(event,'保存失败')}finally{working.value=false}}
async function remove(item:any){if(!window.confirm(`删除“${item.name||relationshipName(item)}”？被场景引用的角色或地点不会被删除。`))return;try{await shortDramaApi.deleteWorldItem(projectId.value,active.value,item.id);await load()}catch(event:any){error.value=apiMessage(event,'删除失败')}}
function editVariant(item:any){variantEditingId.value=item.id;variantForm.value={name:item.name,description:item.description,wardrobe:item.wardrobe,hairstyle:item.hairstyle,makeup:item.makeup,primary_resource_id:item.primary_resource_id,reference_resource_ids:[...(item.reference_resource_ids||[])],source_references:[...(item.source_references||[])]}}
async function saveVariant(){if(!editingId.value||!variantForm.value.name)return;working.value=true;try{if(variantEditingId.value)await shortDramaApi.updateCharacterVariant(projectId.value,editingId.value,variantEditingId.value,variantForm.value);else await shortDramaApi.createCharacterVariant(projectId.value,editingId.value,variantForm.value);await load();const current=world.value.characters.find(item=>item.id===editingId.value);if(current)form.value=structuredClone(current);resetVariant()}catch(event:any){error.value=apiMessage(event,'造型保存失败')}finally{working.value=false}}
async function removeVariant(id:number){if(!editingId.value||!window.confirm('删除这个角色造型？'))return;try{await shortDramaApi.deleteCharacterVariant(projectId.value,editingId.value,id);await load();const current=world.value.characters.find(item=>item.id===editingId.value);if(current)form.value=structuredClone(current)}catch(event:any){error.value=apiMessage(event,'造型删除失败')}}
function relationshipName(item:WorldRelationship){const source=world.value.characters.find(v=>v.id===item.source_character_id)?.name||`#${item.source_character_id}`;const target=world.value.characters.find(v=>v.id===item.target_character_id)?.name||`#${item.target_character_id}`;return `${source} → ${target}`}
function chooseResources(items:ResourceItem[]){const next=new Map(selectedResources.value);for(const item of items)next.set(item.id,item);selectedResources.value=next;const ids=[...next.keys()];form.value.reference_resource_ids=ids;if(active.value==='characters'||active.value==='locations'){if(!form.value.primary_resource_id)form.value.primary_resource_id=items[0]?.id||null}else if(active.value==='props'&&!form.value.resource_id)form.value.resource_id=items[0]?.id||null}
function removeResource(id:number){selectedResources.value.delete(id);selectedResources.value=new Map(selectedResources.value);form.value.reference_resource_ids=(form.value.reference_resource_ids||[]).filter((value:number)=>value!==id);if(form.value.primary_resource_id===id)form.value.primary_resource_id=null;if(form.value.resource_id===id)form.value.resource_id=null}
function openMedia(item:ResourceItem){preview.value={id:item.id,filename:item.filename,media_type:item.media_type,mime:item.mime,width:item.width,height:item.height,duration:item.duration}}
function refs(item:any){return item.source_references||[]}
function resources(item:any){return item.reference_resource_ids||[]}
onMounted(load)
</script>

<template>
  <div class="v2-page world-page">
    <header class="page-head"><div><button class="back" @click="router.push(`/v2/drama/projects/${projectId}`)">← 项目概览</button><h1>角色与世界设定</h1><p>从已确认剧本提取候选，再由人工确认、补全视觉资料与连续性约束。</p></div><div class="head-actions"><V2Button variant="ghost" @click="router.push(`/v2/drama/projects/${projectId}/screenplay`)">剧本工作台</V2Button><V2Button variant="ghost" @click="router.push(`/v2/drama/projects/${projectId}/storyboard`)">分镜工作台</V2Button><V2Button variant="primary" :disabled="working" @click="extract">{{ working?'处理中…':'从剧本提取候选' }}</V2Button></div></header>
    <p v-if="error" class="banner error">{{ error }}</p><p v-if="notice" class="banner notice">{{ notice }}</p>
    <section v-if="candidate&&candidate.status==='pending'" class="candidate-panel"><div><StatusBadge tone="warning">待人工确认</StatusBadge><h2>发现 {{ (candidatePayload.characters||[]).length }} 个角色、{{ (candidatePayload.locations||[]).length }} 个地点和 {{ (candidatePayload.relationships||[]).length }} 条关系</h2><p>来源定位会随候选写入。{{ candidate.conflicts.length?`${candidate.conflicts.length} 项与现有人工设定同名，将保留现有内容。`:'没有发现同名冲突。' }}</p></div><div class="candidate-counts"><span>角色 <b>{{ (candidatePayload.characters||[]).length }}</b></span><span>地点 <b>{{ (candidatePayload.locations||[]).length }}</b></span><span>关系 <b>{{ (candidatePayload.relationships||[]).length }}</b></span><span>冲突 <b>{{ candidate.conflicts.length }}</b></span></div><V2Button variant="primary" :disabled="working" @click="confirmCandidate">确认并写入设定库</V2Button></section>
    <nav class="tabs"><button v-for="tab in tabs" :key="tab.key" :class="{active:active===tab.key}" @click="active=tab.key"><i>{{ tab.icon }}</i>{{ tab.label }}<b>{{ world[tab.key].length }}</b></button><V2Button variant="primary" @click="openCreate">＋ 新建{{ kindLabel }}</V2Button></nav>
    <div v-if="loading" class="empty">正在加载世界设定…</div>
    <section v-else class="card-grid">
      <article v-for="item in currentItems" :key="item.id" class="setting-card">
        <div class="cover"><span>{{ active==='characters'?'人':active==='locations'?'景':active==='props'?'物':'联' }}</span><small v-if="resources(item).length">{{ resources(item).length }} 个参考素材</small></div>
        <div class="card-body"><header><div><h3>{{ active==='relationships'?relationshipName(item):item.name }}</h3><p v-if="active==='relationships'">{{ item.relationship_type }}</p><p v-else-if="active==='characters'">{{ item.identity||item.age_appearance||'角色信息待补充' }}</p><p v-else>{{ item.description||'设定说明待补充' }}</p></div><StatusBadge :tone="item.status==='confirmed'?'success':'neutral'">{{ item.status==='confirmed'?'已确认':'草稿' }}</StatusBadge></header><p class="description">{{ active==='characters'?item.appearance||item.personality:active==='locations'?item.spatial_layout||item.lighting:active==='props'?item.appearance||item.continuity_note:item.description }}</p><div class="source"><span v-if="refs(item).length">来源 {{ refs(item).map((ref:any)=>`第${ref.chapter_number||'?'}章`).join('、') }}</span><span v-else>人工创建 · 无来源定位</span></div><footer><button @click="openEdit(item)">编辑</button><button class="danger" @click="remove(item)">删除</button></footer></div>
      </article><button class="add-card" @click="openCreate">＋<b>新建{{ kindLabel }}</b><span>补充人工设定</span></button><p v-if="!currentItems.length" class="empty wide">当前还没有{{ kindLabel }}设定，可从剧本提取或手工创建。</p>
    </section>

    <GlassDrawer :open="drawer" :title="`${editingId?'编辑':'新建'}${kindLabel}`" @close="drawer=false">
      <form class="form" @submit.prevent="save">
        <template v-if="active==='relationships'"><label>起点角色<select v-model.number="form.source_character_id"><option v-for="item in world.characters" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>目标角色<select v-model.number="form.target_character_id"><option v-for="item in world.characters" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>关系类型<input v-model="form.relationship_type" required></label><label>关系说明<textarea v-model="form.description" rows="6"></textarea></label></template>
        <template v-else><label>名称<input v-model="form.name" required maxlength="160"></label>
          <template v-if="active==='characters'"><label>别名（逗号分隔）<input :value="(form.aliases||[]).join('，')" @input="form.aliases=split(($event.target as HTMLInputElement).value)"></label><label>身份<input v-model="form.identity"></label><label>年龄与观感<input v-model="form.age_appearance"></label><label>外观锚点<textarea v-model="form.appearance" rows="4"></textarea></label><label>性格与行为<textarea v-model="form.personality" rows="4"></textarea></label><label>负面约束（逗号分隔）<input :value="(form.negative_traits||[]).join('，')" @input="form.negative_traits=split(($event.target as HTMLInputElement).value)"></label></template>
          <template v-else-if="active==='locations'"><label>场景说明<textarea v-model="form.description" rows="3"></textarea></label><label>空间布局<textarea v-model="form.spatial_layout" rows="4"></textarea></label><label>时间 / 天气<input v-model="form.time_weather"></label><label>光线<textarea v-model="form.lighting" rows="3"></textarea></label><label>色彩（逗号分隔）<input :value="(form.color_palette||[]).join('，')" @input="form.color_palette=split(($event.target as HTMLInputElement).value)"></label><label>固定物件（逗号分隔）<input :value="(form.fixed_objects||[]).join('，')" @input="form.fixed_objects=split(($event.target as HTMLInputElement).value)"></label></template>
          <template v-else><label>说明<textarea v-model="form.description" rows="3"></textarea></label><label>外观锚点<textarea v-model="form.appearance" rows="4"></textarea></label><label>外观适用范围<input v-model="form.appearance_scope" placeholder="例如：第 1-3 集"></label><label>归属角色<select v-model="form.owner_character_id"><option :value="null">不指定</option><option v-for="item in world.characters" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>连续性备注<textarea v-model="form.continuity_note" rows="4"></textarea></label></template>
          <section class="resource-section"><div><b>参考素材</b><span>可从素材库选择图片、视频或音频</span></div><div class="resource-actions"><select v-model="pickerType"><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select><V2Button type="button" variant="ghost" @click="picker=true">从素材库选择</V2Button></div><div class="resource-list"><article v-for="item in selectedResources.values()" :key="item.id"><button type="button" @click="openMedia(item)">▶</button><span><b>{{ item.filename }}</b><small>{{ item.media_type }} · #{{ item.id }}</small></span><button type="button" @click="removeResource(item.id)">×</button></article><span v-for="id in (form.reference_resource_ids||[]).filter((id:number)=>!selectedResources.has(id))" :key="id" class="existing">已绑定素材 #{{ id }} <button type="button" @click="removeResource(id)">×</button></span></div></section>
          <section v-if="active==='characters'&&editingId" class="variant-section"><header><div><b>角色造型</b><span>维护服装、发型、妆容等阶段性外观</span></div><button type="button" @click="resetVariant">＋ 新造型</button></header><article v-for="item in form.variants||[]" :key="item.id"><span><b>{{ item.name }}</b><small>{{ item.wardrobe||item.description||'未填写造型说明' }}</small></span><button type="button" @click="editVariant(item)">编辑</button><button type="button" @click="removeVariant(item.id)">删除</button></article><div class="variant-form"><input v-model="variantForm.name" placeholder="造型名称"><input v-model="variantForm.wardrobe" placeholder="服装"><input v-model="variantForm.hairstyle" placeholder="发型"><input v-model="variantForm.makeup" placeholder="妆容"><textarea v-model="variantForm.description" rows="2" placeholder="适用阶段与补充说明"></textarea><V2Button type="button" variant="ghost" :disabled="!variantForm.name||working" @click="saveVariant">{{ variantEditingId?'更新造型':'添加造型' }}</V2Button></div></section>
        </template>
        <label>确认状态<select v-model="form.status"><option value="draft">草稿</option><option value="confirmed">已确认</option></select></label><div class="form-actions"><V2Button type="button" variant="ghost" @click="drawer=false">取消</V2Button><V2Button type="submit" variant="primary" :disabled="working">{{ working?'保存中…':'保存设定' }}</V2Button></div>
      </form>
    </GlassDrawer>
    <AssetPicker :open="picker" :media-type="pickerType" multiple @close="picker=false" @select="chooseResources"/>
    <MediaViewer :open="!!preview" :output="preview" @close="preview=null"/>
  </div>
</template>

<style scoped>
.world-page{display:grid;gap:16px}.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px}.page-head h1{margin:10px 0 5px;font-size:31px}.page-head p{margin:0;color:var(--v2-text-muted)}.back{padding:0;color:var(--v2-text-muted);background:none;border:0;cursor:pointer}.head-actions,.resource-actions,.form-actions{display:flex;gap:8px}.banner{margin:0;padding:11px 14px;border-radius:11px}.banner.error{color:var(--v2-danger);background:rgba(255,80,110,.1)}.banner.notice{color:var(--v2-success);background:rgba(80,210,150,.09)}.candidate-panel{padding:18px;display:grid;grid-template-columns:minmax(280px,1fr) auto auto;align-items:center;gap:22px;background:linear-gradient(120deg,rgba(119,132,255,.14),rgba(73,200,178,.07));border:1px solid rgba(130,145,255,.32);border-radius:17px}.candidate-panel h2{margin:8px 0 4px;font-size:18px}.candidate-panel p{margin:0;color:var(--v2-text-muted)}.candidate-counts{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.candidate-counts span{padding:7px 10px;color:var(--v2-text-muted);background:var(--v2-surface-soft);border-radius:8px}.candidate-counts b{color:var(--v2-text)}.tabs{padding:7px;display:flex;align-items:center;gap:6px;background:var(--v2-surface);border:1px solid var(--v2-border);border-radius:14px}.tabs>button:not(.v2-button){padding:10px 14px;display:flex;align-items:center;gap:7px;color:var(--v2-text-muted);background:none;border:0;border-radius:9px;cursor:pointer}.tabs>button.active{color:var(--v2-text);background:var(--v2-surface-soft)}.tabs i{font-style:normal}.tabs b{min-width:19px;padding:2px 5px;color:var(--v2-text-subtle);background:rgba(255,255,255,.06);border-radius:10px;font-size:10px}.tabs>.v2-button{margin-left:auto}.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px}.setting-card,.add-card{min-height:310px;overflow:hidden;background:var(--v2-surface);border:1px solid var(--v2-border);border-radius:17px}.cover{height:108px;padding:14px;display:flex;align-items:flex-end;justify-content:space-between;background:radial-gradient(circle at 22% 25%,rgba(126,142,255,.3),transparent 33%),linear-gradient(135deg,rgba(85,104,160,.13),rgba(48,201,165,.1))}.cover>span{width:54px;height:54px;display:grid;place-items:center;color:var(--v2-primary);background:rgba(5,12,25,.55);border:1px solid var(--v2-border);border-radius:50%;font-size:22px}.cover small{color:var(--v2-text-muted)}.card-body{padding:15px}.card-body header{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.card-body h3{margin:0;font-size:17px}.card-body header p,.description{margin:5px 0 0;color:var(--v2-text-muted)}.description{height:44px;overflow:hidden;line-height:1.55}.source{margin-top:13px;padding:8px;color:var(--v2-text-subtle);background:var(--v2-surface-soft);border-radius:8px;font-size:11px}.card-body footer{margin-top:12px;display:flex;justify-content:flex-end;gap:6px}.card-body footer button{padding:6px 10px;color:var(--v2-text-muted);background:none;border:1px solid var(--v2-border);border-radius:7px}.card-body footer .danger{color:var(--v2-danger)}.add-card{display:grid;place-items:center;align-content:center;gap:8px;color:var(--v2-text-muted);background:rgba(255,255,255,.018);border-style:dashed;cursor:pointer}.add-card:first-line{font-size:28px}.add-card span{font-size:12px}.empty{min-height:220px;display:grid;place-items:center;color:var(--v2-text-muted)}.wide{grid-column:1/-1}.form{display:grid;gap:14px}.form>label{display:grid;gap:7px;color:var(--v2-text-muted);font-size:13px}input,select,textarea{width:100%;padding:10px 11px;color:var(--v2-text);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:9px;outline:none}textarea{resize:vertical}.resource-section{padding:13px;display:grid;gap:11px;background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:11px}.resource-section>div:first-child{display:grid;gap:3px}.resource-section span{color:var(--v2-text-muted);font-size:11px}.resource-actions select{flex:1}.resource-list{display:grid;gap:6px}.resource-list article{padding:7px;display:flex;align-items:center;gap:8px;background:rgba(0,0,0,.13);border-radius:8px}.resource-list article>span{min-width:0;display:grid;flex:1}.resource-list article b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--v2-text)}.resource-list button,.existing button{color:var(--v2-text-muted);background:none;border:0}.existing{padding:7px;background:rgba(0,0,0,.12);border-radius:7px}.form-actions{justify-content:flex-end;margin-top:4px}@media(max-width:760px){.page-head{align-items:flex-start;flex-direction:column}.head-actions{width:100%;flex-wrap:wrap}.candidate-panel{grid-template-columns:1fr}.tabs{overflow:auto}.tabs>button:not(.v2-button){flex:none}.tabs>.v2-button{position:fixed;right:18px;bottom:20px;z-index:20;box-shadow:0 10px 30px rgba(0,0,0,.35)}.card-grid{grid-template-columns:1fr}.setting-card{min-height:290px}}
.variant-section{padding:13px;display:grid;gap:9px;border:1px solid var(--v2-border);border-radius:11px}.variant-section>header,.variant-section>article{display:flex;align-items:center;gap:7px}.variant-section>header>div,.variant-section>article>span{min-width:0;display:grid;flex:1;gap:3px}.variant-section span{color:var(--v2-text-muted);font-size:11px}.variant-section button{padding:5px 8px;color:var(--v2-text-muted);background:none;border:1px solid var(--v2-border);border-radius:7px}.variant-form{display:grid;grid-template-columns:1fr 1fr;gap:7px}.variant-form textarea,.variant-form>.v2-button{grid-column:1/-1}
</style>
